import React, { useState } from "react";
import { FaSearch, FaEdit, FaTrash, FaFilter, FaCog } from "react-icons/fa";
import SidebarLayout from "./SidebarLayout";
import CustomTable from "./reusable/CustomTable";
import events from "../../assets/eventsarray";

const ManageEvents = () => {
  const [Events] = useState(events);
  const [searchTerm, setSearchTerm] = useState("");
  const [visibleColumns, setVisibleColumns] = useState({
    title: true,
    date: true,
    type: true,
    status: true,
  });

  const [showSettings, setShowSettings] = useState(false);
  const [showFilters, setShowFilters] = useState(false);
  const [filters, setFilters] = useState({
    status: "",
    date: "",
    type: "",
  });

  // Filtering logic
  const filteredEvents = Events.filter((event) => {
    const matchTitle = event.title.toLowerCase().includes(searchTerm.toLowerCase());
    const matchStatus = filters.status ? event.status === filters.status : true;
    const matchDate = filters.date ? event.date === filters.date : true;
    const matchType = filters.type ? event.type === filters.type : true;

    return matchTitle && matchStatus && matchDate && matchType;
  });

  // Get unique options
  const statusOptions = [...new Set(events.map((e) => e.status))];
  const typeOptions = [...new Set(events.map((e) => e.type))];
  const dateOptions = [...new Set(events.map((e) => e.date))];

  return (
    <SidebarLayout>
      <div className="w-full bg-[#FDF8F3] p-6">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-2xl font-semibold">Event Management</h1>
          <button className="bg-[#F48F0F] text-white px-4 py-2 rounded-full hover:opacity-90">
            Schedule a new event
          </button>
        </div>

        {/* Search + Icons */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-4 relative">
          {/* Search Input */}
          <div className="flex items-center bg-white rounded-full px-4 py-2 w-full sm:max-w-md border border-gray-300">
            <FaSearch className="text-gray-400 mr-2" />
            <input
              type="text"
              placeholder="Search by Event Name"
              className="outline-none w-full text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          {/* Icons */}
          <div className="flex items-center gap-4 self-end sm:self-auto">
            <div className="relative">
              <FaFilter
                className="text-[#F48F0F] cursor-pointer text-xl"
                onClick={() => setShowFilters(!showFilters)}
              />
              {showFilters && (
                <div className="absolute top-8 right-10 z-20 bg-white shadow-lg rounded-md p-4 w-64 border border-gray-200 space-y-3">
                  {/* Status Filter */}
                  <div>
                    <label className="block text-sm font-medium mb-1">Status</label>
                    <select
                      className="w-full border border-gray-300 rounded px-2 py-1 text-sm"
                      value={filters.status}
                      onChange={(e) =>
                        setFilters({ ...filters, status: e.target.value })
                      }
                    >
                      <option value="">All</option>
                      {statusOptions.map((status, i) => (
                        <option key={i} value={status}>
                          {status}
                        </option>
                      ))}
                    </select>
                  </div>

                  {/* Date Filter */}
                  <div>
                    <label className="block text-sm font-medium mb-1">Date</label>
                    <select
                      className="w-full border border-gray-300 rounded px-2 py-1 text-sm"
                      value={filters.date}
                      onChange={(e) =>
                        setFilters({ ...filters, date: e.target.value })
                      }
                    >
                      <option value="">All</option>
                      {dateOptions.map((date, i) => (
                        <option key={i} value={date}>
                          {date}
                        </option>
                      ))}
                    </select>
                  </div>

                  {/* Type Filter */}
                  <div>
                    <label className="block text-sm font-medium mb-1">Category</label>
                    <select
                      className="w-full border border-gray-300 rounded px-2 py-1 text-sm"
                      value={filters.type}
                      onChange={(e) =>
                        setFilters({ ...filters, type: e.target.value })
                      }
                    >
                      <option value="">All</option>
                      {typeOptions.map((type, i) => (
                        <option key={i} value={type}>
                          {type}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>
              )}
            </div>

            {/* Settings Icon */}
            <div className="relative">
              <FaCog
                className="text-[#F48F0F] cursor-pointer text-xl"
                onClick={() => setShowSettings(!showSettings)}
              />
              {showSettings && (
                <div className="absolute top-8 right-0 bg-white shadow-lg rounded-md p-4 z-20 border border-gray-200">
                  {Object.keys(visibleColumns).map((col) => (
                    <label key={col} className="block text-sm mb-2">
                      <input
                        type="checkbox"
                        checked={visibleColumns[col]}
                        onChange={() =>
                          setVisibleColumns({
                            ...visibleColumns,
                            [col]: !visibleColumns[col],
                          })
                        }
                        className="mr-2"
                      />
                      Show {col.charAt(0).toUpperCase() + col.slice(1)}
                    </label>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Table */}
        <CustomTable
          cols={[
            {
              key: "title",
              label: "Event Name",
            },
            {
              key: "date",
              label: "Date",
            },
            {
              key: "type",
              label: "Category",
            },
            {
              key: "status",
              label: "Status",
            },
          ]}
          rows={filteredEvents.map((event) => ({
            ...event,
            actions: (
              <>
                <FaEdit className="text-[#F48F0F] cursor-pointer" />
                <FaTrash className="text-[#F48F0F] cursor-pointer" />
              </>
            ),
          }))}
          visibleCols={visibleColumns}
        />
      </div>
    </SidebarLayout>
  );
};

export default ManageEvents;
